    || '. Build area: ' || (deed_radius(1) * 2 + 1) || '×' || (deed_radius(1) * 2 + 1) || ' tiles round the totem.'
    || case when made is null then '' else ' Settlement crate placed beside it.' end, 'system');
end $function$
